import { Component, Inject, Input, input } from '@angular/core';
import { SectionRes } from '../../../interfaces/bundlemanage.interface';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { BundlemanageService } from '../../../services/bundle-manage/bundlemanage.service';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { IndexingService } from '../../../services/indexing/indexing.service';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { CdkDragDrop, DragDropModule, moveItemInArray } from '@angular/cdk/drag-drop';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';

@Component({
  selector: 'app-genindex',
  standalone: true,
  imports: [CommonModule, FormsModule, InputComponent, MatCheckboxModule, ButtonComponent, DragDropModule, IconComponent, MatMenuModule],
  templateUrl: './genindex.component.html',
  styleUrl: './genindex.component.scss'
})
export class GenindexComponent {
  nCaseid: string;
  activesaction: SectionRes;
  isCoverpg: boolean = true;
  isIndexpg: boolean = true;
  cHyperlinktype: string = 'T'
  indexGeneration: boolean = false;
  isIndexFailed: boolean = false;
  socketSubscription: Subscription;
  responceMsg: string = 'Indexing is in progress. Please wait...';
  timePeriods = [
    { key: 'Bundle', dbkey: 'cBundletag', isShow: false, isedit: false, dwidth: 65, width: 50 },
    { key: 'Tab', dbkey: 'cTab', isShow: true, isedit: false, dwidth: 52, width: 70 },
    { key: 'Name', dbkey: 'cFilename', isShow: true, isedit: false, dwidth: 65, width: '*' },
    { key: 'Date', dbkey: 'dIntrestDt', isShow: true, isedit: false, dwidth: 115, width: 70 },
    { key: 'Description', dbkey: 'cDescription', isShow: true, isedit: false, dwidth: 97, width: 80 },
    { key: 'Page', dbkey: 'cRefpage', isShow: true, isedit: false, dwidth: 58, width: 40 },
    { key: 'Kind', dbkey: 'kind', isShow: false, isedit: false, dwidth: 57, width: 30 },
    { key: 'Exhibit', dbkey: 'cExhibitno', isShow: true, isedit: false, dwidth: 90, width: 75 },
    { key: 'Author', dbkey: 'cAuthor', isShow: false, isedit: false, dwidth: 90, width: 75 }
  ];

  tablecols: any = [
    { id: 2, 'name': 'Tab', 'key': 'tab', 'isshow': true, },
    { id: 3, 'name': 'Exhibit No.', 'key': 'exhibit', 'isshow': true, },
    { id: 4, 'name': 'Name', 'key': 'name', 'isshow': true, },
    { id: 5, 'name': 'Pagination', 'key': 'page', 'isshow': true, },
    { id: 6, 'name': 'Kind', 'key': 'Kind', 'isshow': true, },
    { id: 7, 'name': 'Date', 'key': 'date', 'isshow': true, },
    { id: 8, 'name': 'Description', 'key': 'desc', 'isshow': true, },
    { id: 9, 'name': 'Author', 'key': 'author', 'isshow': false, }
  ];
  
  cFilename: string;
  constructor(private indexS: IndexingService, private dialogRef: MatDialogRef<GenindexComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any, private bundleS: BundlemanageService, private ss: SocketService) {
    this.nCaseid = data['nCaseid'];
    this.activesaction = data['activeSection'];
    this.cFilename = 'Master index' // this.activesaction.cFolder;
    this.socketSubscription = this.ss.getIndexs().subscribe((res: any) => {
      if (res.data.type != 'F' || res.data.type != 'C') {
        this.responceMsg = res.data.message;
      } if (res.data.type == 'F') {
        this.isIndexFailed = true;
        this.indexGeneration = false;
        this.responceMsg = res.data.message;
      }
      if (res.data.type == 'C') {
        this.indexGeneration = false;
        this.dialogRef.close({ isSave: true, nBundledetailid: res.data.nBundledetailid, cName: res.data.cName });
      }
    })
  }

  ngOnInit(): void {
    this.cHyperlinktype = 'T';
  }


  items = [
    { title: 'Bundle', isEditable: false },
    { title: 'Tab', isEditable: false },
    { title: 'Date df interest', isEditable: false },
    { title: 'Description', isEditable: false },
    { title: 'Page', isEditable: false }
  ];
  draggedIndex: number | null = null;
  targetIndex: number | null = null;

  onDragStart(event: DragEvent, index: number) {
    this.draggedIndex = index;
    event.dataTransfer?.setData('text/plain', event.currentTarget.toString());
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
  }

  onDragEnter(event: DragEvent, index: number) {
    if (this.draggedIndex !== null && this.draggedIndex !== index) {
      this.targetIndex = index;
      this.moveItem(this.draggedIndex, this.targetIndex);
      this.draggedIndex = this.targetIndex;
    }
  }

  onDragEnd() {
    this.draggedIndex = null;
    this.targetIndex = null;
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
  }

  moveItem(fromIndex: number, toIndex: number) {
    const item = this.items.splice(fromIndex, 1)[0];
    this.items.splice(toIndex, 0, item);
  }

  ngOnDestroy(): void {
    this.socketSubscription.unsubscribe();
  }

  drop(event: CdkDragDrop<string[]>) {
    moveItemInArray(this.timePeriods, event.previousIndex, event.currentIndex);
  }

  geterateIndex() {
    if (this.indexGeneration) { return; }
    if (this.cFilename.trim() == '') { this.cFilename = this.activesaction.cFolder; }
    this.isIndexFailed = false;
    this.indexGeneration = true;
    this.responceMsg = 'Indexing is in progress. Please wait...';
    var column = this.timePeriods.filter(e => e.isShow).map(x => JSON.stringify([x.key, x.dbkey, x.width])).join(',');
    this.indexS.generateIndexing(this.nCaseid, this.cFilename, this.activesaction.nSectionid, this.cHyperlinktype, this.isCoverpg, this.isIndexpg, column

    ).then(res => {
      if (res) {
        console.log(res);
      } else {
        this.indexGeneration = false;
        this.isIndexFailed = true;
        this.responceMsg = 'Indexing failed. Please try again.';
      }
    })

  }


  close() {
    this.dialogRef.close();
  }
}
