import { Component, Inject } from '@angular/core';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ProgressComponent } from '../../../../../shared/components/progress/progress.component';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { DragDropModule } from '@angular/cdk/drag-drop';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { BatchfileService } from '../../../../services/batchfile/batchfile.service';
import { SocketService } from '../../../../../core/services/socket/socket.service';
import { SectionRes } from '../../../../interfaces/bundlemanage.interface';
import { BatchDownloadRes, BatchUploadReq, headerColumns } from '../../../../interfaces/batchfile.interface';
import { UploadManagementService } from '../../../../services/upload/upload-management/upload-management.service';
import { FileStorageService } from '../../../../services/upload/file-storage/file-storage.service';
import { HttpClientModule } from '@angular/common/http';
import { UploadService } from '../../../../services/upload/upload.service';
import { CheckDuplicacyService } from '../../../../services/upload/check-duplicacy/check-duplicacy.service';
import { fileUploadMDL, uploadMasterMDL } from '../../../../interfaces/upload.interface';

@Component({
  selector: 'app-uploadbatch',
  standalone: true,
  imports: [ButtonComponent, IconComponent, ProgressComponent, CommonModule, MatMenuModule, DragDropModule, HttpClientModule],
  providers: [FileStorageService, UploadManagementService, UploadService, CheckDuplicacyService],
  templateUrl: './uploadbatch.component.html',
  styleUrl: './uploadbatch.component.scss'
})
export class UploadbatchComponent {
  timePeriods: headerColumns[] = [{ key: 'Bundle', dbkey: 'cBundletag', isShow: false, isedit: false, dwidth: 65, width: 50, isHide: true },
    { key: 'Tab', dbkey: 'cTab', isShow: true, isedit: false, dwidth: 52, width: 70, isHide: true },
    { key: 'Name', dbkey: 'cFilename', isShow: true, isedit: false, dwidth: 65, width: '*', isHide: true },
    { key: 'Date', dbkey: 'dIntrestDt', isShow: true, isedit: false, dwidth: 121, width: 70, isHide: true },
    { key: 'Description', dbkey: 'cDesc', isShow: true, isedit: false, dwidth: 97, width: 80, isHide: true },
    { key: 'Page', dbkey: 'cRefpage', isShow: true, isedit: false, dwidth: 58, width: 40, isHide: true },
    { key: 'Kind', dbkey: 'kind', isShow: false, isedit: false, dwidth: 57, width: 30, isHide: true },
    { key: 'Exhibit', dbkey: 'cExhibitno', isShow: true, isedit: false, dwidth: 90, width: 75, isHide: true },
    { key: 'Author', dbkey: 'cAuthor', isShow: false, isedit: false, dwidth: 90, width: 75, isHide: true }];

  column: string[][] = [];
  fileColumns: string[][] = [];
  isMissmatch: boolean = false;
  activeSection: SectionRes;
  nCaseid: string;
  cFilename: string = '';
  uploadedPath: string = '';
  uploadStatus: string = '';
  isUpload: boolean = false;
  process: number = 100;
  submit: boolean = false;
  batchfile: fileUploadMDL;
  isUpdated: boolean = false;

  batchMaster: uploadMasterMDL[] = [];
  constructor(private MatDialogRef: MatDialogRef<UploadbatchComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any, private bfService: BatchfileService, private ss: SocketService,
    public upload: UploadManagementService,
    public store: FileStorageService
  ) {
    this.nCaseid = data['nCaseid'];
    this.activeSection = data['activeSection'];
  }


  ngOnDestroy(): void {
    // this.socketSubscription.unsubscribe();
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
  }

  ngOnInit(): void {
    this.store.setCateId(this.nCaseid, true);
    this.getbatchColumns();
  }

  async getbatchColumns() {
    const res = await this.bfService.getBatchcolumns(this.nCaseid, this.activeSection.nSectionid)
    if (res) {
      this.fileColumns = res[0] ? JSON.parse(`[${res[0].cColumn}]`) : [];
      this.checkForKeyMismatch();
    }
  }



  async readFileColumns(path) {
    const res: BatchDownloadRes = await this.bfService.getFilecolumn(path)
    if (res) {
      
      this.column = res.data && res.data.length ? res.data : [];
      this.checkForKeyMismatch();
    }
  }

  checkForKeyMismatch() {
    var isMissmatch = false;

    if (this.fileColumns.length == 0 || this.column.length == 0) {
      isMissmatch = true;
    };
    // Check for missing keys in fileColumns
    for (let cols of this.fileColumns) {
      const matchingColumn = this.column.filter(e => e.toString() != 'ID').find(x => x.toString() === cols[0]);
      if (!matchingColumn) {
        isMissmatch = true;
        break;
      }
    }

    // Check for extra keys in column
    if (!isMissmatch) {  // Only proceed if no mismatch found yet
      for (let cols of this.column.filter(e => e.toString() != 'ID')) {
        const matchingColumn = this.fileColumns.find(x => x[0].toString() === cols.toString());
        if (!matchingColumn) {
          isMissmatch = true;
          break;
        }
      }
    }

    if (this.column.length && this.fileColumns.length) {
      for (let cols of this.column.filter(e => e.toString() != 'ID')) {
        const matchingColumn = this.fileColumns.find(x => x[0] === cols.toString());
        if (matchingColumn) {
          this.timePeriods.find(e => e.dbkey === matchingColumn[1])['isHide'] = false;
          this.timePeriods.find(e => e.dbkey === matchingColumn[1])['isShow'] = true;
          this.timePeriods.find(e => e.dbkey === matchingColumn[1])['key'] = matchingColumn[0];
        }
      }
    }
    this.isMissmatch = isMissmatch;
  }


  close() {
    this.MatDialogRef.close();
  }

  async updateData() {
    if (this.batchfile.cStatus != 'C') { return }
    if (this.submit) { return }
    let mdl: BatchUploadReq = {} as BatchUploadReq;
    mdl.column = this.timePeriods.filter(e => e.isShow).map(x => JSON.stringify([x.key, x.dbkey])).join(',');
    mdl.nSectionid = this.activeSection.nSectionid;
    mdl.nCaseid = this.nCaseid;
    mdl.cPath = this.uploadedPath;
    this.submit = true
    let res = await this.bfService.uploadBatchfile(mdl)
    if (res) {
      this.submit = false;
      this.isUpdated = true;
      // this.MatDialogRef.close();
    } else {
      this.submit = false;
    }

  }

  async onFileChange(e) {
    let res = await this.upload.startUploadBatch(e.target.files[0], (files) => {
      this.batchfile = files[0];
      this.cFilename = this.batchfile.name + '.' + this.batchfile.filetype;
      this.isUpload = true;
    });
    if (res) {
      this.uploadedPath = `doc/case${this.nCaseid}/${this.batchfile.name}.${this.batchfile.filetype}`
      this.readFileColumns(this.uploadedPath);
    }
  }

  getFile() {
    const fileInput: any = document.querySelector('input[type="file"]');
    fileInput.click();
  }

  playPause() {
    
    if (this.batchfile.cStatus == 'PSD') {
      this.upload.resumeUpload(this.batchfile);
      this.batchfile.cStatus = 'I';
      return;
    }
    this.upload.pauseUpload(this.batchfile);
    this.batchfile.cStatus = 'PSD';
  }


}
