import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, ViewChild } from '@angular/core';
import { MatMenuModule } from '@angular/material/menu';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { HeaderService } from '../../../../core/services/header/header.service';
import { ActivatedRoute, Router } from '@angular/router';
import { BundlemanageService } from '../../../services/bundle-manage/bundlemanage.service';
import { SectionBuilderReq, SectionRes } from '../../../interfaces/bundlemanage.interface';
import { SectionCreationComponent } from '../section-creation/section-creation.component';
import { MatDialog } from '@angular/material/dialog';
import { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { SectionComponent } from '../../../../shared/components/myfiles/section/section.component';
import { GenindexComponent } from '../genindex/genindex.component';
import { UploadbatchComponent } from '../batch/uploadbatch/uploadbatch.component';
import { DownloadbatchComponent } from '../batch/downloadbatch/downloadbatch.component';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { PaginationService } from '../../../services/pagination/pagination.service';
import { getPaginationRes, paginationSocketRes } from '../../../interfaces/pagination.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { HyperlinkComponent } from '../../hyperlink/hyperlink.component';
import { CommunicationService } from '../../../../shared/services/communication/communication.service';
import { HyperlinkService } from '../../../services/hyperlink/hyperlink.service';
import { Title } from '@angular/platform-browser';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';
import { RolepermitService } from '../../../../core/services/permission/rolepermit.service';
import { ACTIONBAR_EVENTS } from '../../../../shared/interfaces/actionbar.interface';

@Component({
  selector: 'app-bundlemanagement',
  standalone: true,
  imports: [CommonModule, MatMenuModule, ButtonComponent, IconComponent, FileexplorerComponent, SectionComponent, MatTooltipModule, HyperlinkComponent],
  templateUrl: './bundlemanagement.component.html',
  styleUrl: './bundlemanagement.component.scss'
})
export class BundlemanagementComponent {
  @ViewChild('fileExplorer') fileExplorer: FileexplorerComponent;
  @ViewChild('sectionCom') sectionCom: SectionComponent;
  openbatch: boolean = false;
  openhyperlink: boolean = false;
  actionbaropen: boolean = false;
  nCaseid: string;
  nSectionid: string;
  activeSection: SectionRes;
  socketSubscription: Subscription;
  socketSubscription2: Subscription;
  private evsubscription: Subscription;
  intervalConvert: any;
  lastRecord: { queueLength: number } | null = null;
  isCanUpload: boolean = false;
  constructor(public hs: HeaderService, private route: ActivatedRoute, private bundleS: BundlemanageService, private cs: CommunicationService,
    private dialog: MatDialog, private ss: SocketService, public cf: CommonfunctionService, private paginationS: PaginationService, private tost: TostbarService,
    private hyperlinkService: HyperlinkService, private cdr: ChangeDetectorRef, private titleService: Title,
    private userPermissionService: UserPermissionService, private rolePermit: RolepermitService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    try {
      debugger;
      this.hs.jFilter = params && params["jFilter"] ? params["jFilter"] : this.hs.jFilter;
      if (this.hs.jFilter?.cSearch) {
        this.hs.isGlobalSearch = true;
        this.hs.search_within = this.hs.jFilter.cWithin;
      }
    } catch (error) {

    }

    this.nCaseid = params && params["id"] ? params["id"] : 0;
    // this.cdr.detectChanges();
    this.socketSubscription = this.ss.getPagination().subscribe((res: any) => {
      const data: paginationSocketRes = res?.data?.data || [];
      if (data && data.nCaseid == this.nCaseid) {
        console.log('pagination data', data);
        if (data.cStatus == 'P') {
          this.cf.paginationdata = data;
          if (!this.cf.isPagination) {
            this.cf.isPagination = true;
          }
        }
        if (data.cStatus == 'C') {
          this.cf.isPagination = false;
          this.tost.openSnackBar('All files successfully paginated', '');
          this.cf.paginationdata = {};
        } if (data.cStatus == 'S') {
          this.cf.isPagination = false;
          this.cf.paginationdata = {};
        }
      }
    })

    this.socketSubscription2 = this.ss.getUploades().subscribe(async (res: any) => {
      if (res && res.event && ['CONVERTING-PROCESS', 'CONVERTING-START', 'CONVERTING-SUCCESS', 'CONVERTING-ERROR', 'CONVERTING-FAILED', 'FILE-INSERT-COMPLETE'].includes(res.event)) {
        const data: any = res?.data || [];
        if (data && data.nCaseid == this.nCaseid) {
          if (['CONVERTING-PROCESS', 'CONVERTING-START', 'CONVERTING-SUCCESS', 'CONVERTING-FAILED'].includes(res.event)) {
            if (!this.cf.convertData?.queueLength) {
              let res = await this.getConvertingLength(this.nCaseid);
              this.cf.convertData.queueLength = res.queueLength;
              if (!this.cf.convertData.total_prog) {
                this.cf.convertData.total_prog = res.queueLength
              } else if (this.cf.convertData.total_prog < this.cf.convertData.queueLength) {
                this.cf.convertData.total_prog = res.queueLength
              }
            }

            if (!this.cf.isConvert && this.cf.convertData?.queueLength) {
              this.cf.isConvert = true;
            }
          }
          if (['FILE-INSERT-COMPLETE', 'CONVERTING-ERROR', 'CONVERTING-FAILED'].includes(res.event)) {
            let res = await this.getConvertingLength(this.nCaseid);
            this.cf.convertData.queueLength = res.queueLength;
            if (!this.cf.convertData.total_prog && this.cf.convertData.queueLength) {
              this.cf.convertData.total_prog = res.queueLength
            } else if (this.cf.convertData.total_prog < this.cf.convertData.queueLength) {
              this.cf.convertData.total_prog = res.queueLength
            }
            if (!this.cf.convertData?.queueLength && this.cf.isConvert) {
              this.cf.isConvert = false;
              this.tost.openSnackBar('All files Proceed', '');
              this.cf.convertData = { queueLength: 0, total_prog: 0 };
            }
          }
        }
      }
    })

  }

  ngOnDestroy(): void {
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
    if (this.evsubscription) {
      this.evsubscription.unsubscribe();
    }
    this.sectionCom = null;
    this.fileExplorer.ngOnDestroy();
    this.socketSubscription.unsubscribe();
    this.socketSubscription2.unsubscribe();
  }

  async ngOnInit() {
    this.titleService.setTitle('Admin Panel');
    this.cf.isPagination = false;
    this.cf.paginationdata = {};
    this.evsubscription = this.cs.functionCalled$.subscribe(async (e) => {
      if (e.event == 'START-HYPERLINK') {
        if (this.nCaseid && this.nSectionid) {
          this.hyperlinkService.startHyperlink(this.nCaseid, this.nSectionid, null, (e.nBundledetailid || null), e.mode, false, e.cKeeptype, e.isDeep);
        }
      }
    })

    this.getpaginationdata(this.nCaseid);
    await this.userPermissionService.userPermissionList(this.nCaseid) || [];
    this.verifyPermission();
    setTimeout(() => {
      this.hs.updatePath('Admin Panel');
      this.hs.updateisCase(true);
    }, 10);
  }

  FileEvent(e) {

    if (e.event == 'HYPERLINK') {
      this.hyperlinkService.startHyperlink(this.nCaseid, this.nSectionid, null, (e.nBundledetailid || null), e.mode, e.cIsindex, e.cKeeptype, e.isDeep);
    }
  }

  ngAftrViewInit() {
  }


  changeSection(x) {
    this.activeSection = x;
    this.nSectionid = this.activeSection.nSectionid;
  }

  createSection(x?) {
    var data: object = {
      nCaseid: this.nCaseid,
      nSectionid: x && x.nSectionid ? x.nSectionid : null,
      cFolder: x && x.cFolder ? x.cFolder : null
    }
    this.openModle(SectionCreationComponent, data, '485px')
  }


  openModle(component, data: SectionBuilderReq, width?: string, height?: string, x?) {
    const dialogRef = this.dialog.open(component, {
      width: width ? width : 'fit-content',
      height: height ? height : 'fit-content',
      maxHeight: '99vh',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      data: data
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result && result.isSave) {
        if (component == SectionCreationComponent) {
          if (data["nSectionid"]) {
            this.activeSection.cFolder = dialogRef.componentInstance["cFolder"]
          } else {
            this.bundleS.getSections(this.nCaseid).then(res => { this.sectionCom.sectionlist = res; })
          }
        }
        if (component == GenindexComponent) {
          if (!this.fileExplorer.nBundleid) {
            this.fileExplorer.fileCom.getFileList(1, 'ALL');
            const index = this.cf.viewlist.findIndex(e => e.nBundledetailid === result.nBundledetailid);
            if (index > -1) {
              this.cf.viewlist.splice(index, 1);
            }
            this.fileExplorer.viewFile(result);
          }
        }
      }
    })
  }

  async deleteSection() {
    if (this.activeSection["cFoldertype"] == 'M' || this.activeSection["cFoldertype"] == 'C') {
      var mdl: SectionBuilderReq = { nCaseid: this.nCaseid, nSectionid: this.activeSection.nSectionid ? this.activeSection.nSectionid : null, cFolder: this.activeSection.cFolder, cFoldertype: this.activeSection.cFoldertype, permission: 'D' };
      let res: any = await this.bundleS.sectionBuilder(mdl);
      if (res) {
        this.bundleS.getSections(this.nCaseid).then(res => {
          this.sectionCom.sectionlist = res;
          this.sectionCom.sectionChange(res.filter(e => e.cFoldertype == 'MB')[0]);
          this.cdr.detectChanges()
        });
      }
    }
  }

  addNewFolder() {
    this.fileExplorer.folderCom.addNewBundle(null);
  }

  upload() {
    let nBundleid = this.fileExplorer.nBundleid;
    // let urls = `${window.location.origin}/upload/uploadmanager/${btoa(`{"c":${this.nCaseid},"s":${this.nSectionid},"b":${nBundleid}}`)}`;

    const obj = {
      c: this.nCaseid,
      s: this.nSectionid,
      b: nBundleid
    }
    let urls = `${window.location.origin}/upload/uploadmanager/${btoa(JSON.stringify(obj))}`; //`{"c":${this.nCaseid},"s":${this.nSectionid},"b":${nBundleid}}`

    console.log(urls);
    window.open(urls, '_blank');
  }



  generateIndexing() {
    var data: object = {
      nCaseid: this.nCaseid,
      activeSection: this.activeSection
    }
    this.openModle(GenindexComponent, data)
  }


  screenSharing() {
    // this.openModle(RoomComponent, {})
  }

  // generateIndexing() {
  //   this.indexS.generateIndexing(this.nCaseid, this.activeSection.nSectionid).then(res => {
  //     console.log(res);
  //   })
  // }

  batchupload() {
    // const dialogRef = this.dialog.open(UploadbatchComponent, {
    //   width: '900px',
    //   height: 'fit-content',
    //   maxHeight: '99vh',
    //   panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
    //   data: {}
    // });
    // dialogRef.afterClosed().subscribe(result => {

    // })

    var data: object = {
      nCaseid: this.nCaseid,
      activeSection: this.activeSection
    }
    this.openModle(UploadbatchComponent, data, '900px', 'fit-content')
  }

  batchuploadlog() {
    this.cf.goto('/admin/batchlog', { id: this.nCaseid })
  }



  batchDownload() {

    var data: object = {
      nCaseid: this.nCaseid,
      activeSection: this.activeSection
    }
    this.openModle(DownloadbatchComponent, data, 'fit-content', 'fit-content')
  }

  get_progres(x) {
    var bl: any = (x.comp_progres ? x.comp_progres : 0) / (x.total_prog ? x.total_prog : 100) * 100;
    return parseInt(bl);
  }

  async stopPagination(paginationdata) {
    var mdl: any = {};
    mdl.nPtaskid = paginationdata.nPtaskid
    let res: boolean = await this.paginationS.stopPagination(mdl);
    if (res) {
      this.cf.paginationdata.total_prog = paginationdata.comp_progres + 1;
    }
  }

  async getpaginationdata(nCaseid) {
    let res: getPaginationRes = await this.paginationS.getPaginationData(nCaseid);
    if (res && res[0] && res[0]['msg'] == 1) {
      this.cf.paginationdata = res[0];
      if (this.cf.paginationdata.total_prog > this.cf.paginationdata.comp_progres) {
        this.cf.isPagination = true;
        this.cf.paginationIDs = this.cf.paginationdata.jIds;
      }
    }
  }
  calcCompPprogres(completedFiles, totalFiles) {
    if (totalFiles === 0) {
      return 0; // To avoid division by zero
    }
    return ((completedFiles / totalFiles) * 100).toFixed();
  }


  calcPendingProgress(pendingFiles, totalFiles) {
    if (totalFiles === 0) {
      return 0; // To avoid division by zero
    }
    const completedFiles = totalFiles - pendingFiles; // Calculate completed files
    return parseFloat(((completedFiles / totalFiles) * 100).toFixed(2)); // Return completed percentage
  }

  actionevents(ev) {
    if (ev.event == ACTIONBAR_EVENTS.OPEN) {
      this.actionbaropen = true;
    }
    if (ev.event == ACTIONBAR_EVENTS.CLOSE) {
      this.actionbaropen = false;
    }
  }


  async getConvertingLength(nCaseid: string): Promise<{ queueLength: number }> {
    // If there's already a pending timeout, return the last record
    if (this.intervalConvert && this.lastRecord) {
      return this.lastRecord;
    }

    // If no timeout is set, make immediate API call
    if (!this.intervalConvert) {
      this.lastRecord = await this.bundleS.getConvertingLength(nCaseid);

      // Set timeout for the next update
      this.intervalConvert = setTimeout(async () => {
        try {
          this.lastRecord = await this.bundleS.getConvertingLength(nCaseid);

          if (!this.lastRecord?.queueLength && this.cf.isConvert) {
            this.cf.isConvert = false;
            this.tost.openSnackBar('All files Proceed', '');
            this.cf.convertData = { queueLength: 0, total_prog: 0 };
          }
        } catch (error) {
          console.error('Error in delayed conversion check:', error);
        } finally {
          clearTimeout(this.intervalConvert);
          this.intervalConvert = null;
        }
      }, 1000);
    }

    return this.lastRecord;
  }

  async verifyPermission() {
    this.isCanUpload = this.rolePermit.verifyPermission('UL') && this.rolePermit.verifyPermission('UM');
  }
}