import { Component, Input } from '@angular/core';
import { HyperlinkService } from '../../services/hyperlink/hyperlink.service';
import { hyperlinkList } from '../../interfaces/bundlemanage.interface';
import { SocketService } from '../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { BadgeComponent } from '../../../shared/components/badge/badge.component';

@Component({
  selector: 'hyperlink',
  standalone: true,
  imports: [IconComponent,BadgeComponent],
  templateUrl: './hyperlink.component.html',
  styleUrl: './hyperlink.component.scss'
})
export class HyperlinkComponent {
  @Input() nSectionid: string;
  @Input() nCaseid: string;
  onSubscription_current: Subscription;
  constructor(public hyperlinkService: HyperlinkService, private ss: SocketService) {

  }

  async ngOnInit() {
    
    this.hyperlinkService.hyperlinkList = [];
    this.onSubscription_current = this.ss.getHyperlink().subscribe(res => {
      console.warn('Hyperlink', res);
      if (res.event == 'HYPERLINK-RESPONCE') {
        const ind = this.hyperlinkService.hyperlinkList.findIndex(a => a.queueName == res.data.queueName);
        if (ind > -1) {
          this.hyperlinkService.hyperlinkList[ind] = res.data;
        } else {
          this.hyperlinkService.hyperlinkList.push(res.data);
        }
        this.clearUnWanted()
      }
    });

    const res: any = await this.hyperlinkService.getHyperLinks(this.nCaseid);
    if (res) {
      if (res.msg == 1) {
        const list = res.value || [];
        if (list && list.length) {
          this.hyperlinkService.hyperlinkList = list;
          this.clearUnWanted()
        }
      }
    }
  }


  ngOnDestroy(): void {
    if (this.onSubscription_current) {
      this.onSubscription_current.unsubscribe();
    }
  }


  closeHyperLink() {
    this.hyperlinkService.hyperlinkList = [];
  }

  clearUnWanted(){
    this.hyperlinkService.hyperlinkList =  this.hyperlinkService.hyperlinkList.filter(a=>a.nTotal && a.nTotal >0 );
  }
}
