import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, Inject, Input, ViewChild, input } from '@angular/core';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { bundleRes, selectedbundleRes } from '../../../../../shared/interfaces/myfile.interface';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { CdkDragDrop, CdkDragPlaceholder, moveItemInArray } from '@angular/cdk/drag-drop';
import { MyfileService } from '../../../../../shared/services/myfile/myfile.service';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { InputComponent } from '../../../../../shared/components/input/input.component';
import { SectionRes } from '../../../../interfaces/bundlemanage.interface';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { FoldersComponent } from '../../../../../shared/components/myfiles/folders/folders.component';
import { BatchDownloadReq } from '../../../../interfaces/batchfile.interface';
import { BatchfileService } from '../../../../services/batchfile/batchfile.service';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../../core/services/socket/socket.service';
import { environment } from '../../../../../../environments/environment';
import { HeaderService } from '../../../../../core/services/header/header.service';

@Component({
  selector: 'app-downloadbatch',
  standalone: true,
  imports: [CommonModule, MatMenuModule, FoldersComponent, FormsModule, IconComponent, CdkDragPlaceholder, ButtonComponent, InputComponent],
  providers: [MyfileService, BatchfileService],
  templateUrl: './downloadbatch.component.html',
  styleUrl: './downloadbatch.component.scss'
})
export class DownloadbatchComponent {
  @ViewChild(MatMenuTrigger) menuTrigger: MatMenuTrigger;
  downloadPath: string = environment.cloudUrl + environment.downloadpath;
  @ViewChild('folderCom') folderCom: FoldersComponent;
  activeSection: SectionRes;
  nCaseid: string;
  showfolders: boolean = false;
  cFilename: string = '';
  selectedbatchfolder: selectedbundleRes[] = [];
  selectedIDs: string[] = []
  isSepcomponent: boolean = true;
  timePeriods = [
    { key: 'Bundle', dbkey: 'cBundletag', isShow: false, isedit: false, dwidth: 65, width: 50 },
    { key: 'Tab', dbkey: 'cTab', isShow: true, isedit: false, dwidth: 52, width: 70 },
    { key: 'Name', dbkey: 'cFilename', isShow: true, isedit: false, dwidth: 65, width: '*' },
    { key: 'Date', dbkey: 'dIntrestDt', isShow: true, isedit: false, dwidth: 121, width: 70 },
    { key: 'Description', dbkey: 'cDesc', isShow: true, isedit: false, dwidth: 97, width: 80 },
    { key: 'Page', dbkey: 'cRefpage', isShow: true, isedit: false, dwidth: 58, width: 40 },
    { key: 'Kind', dbkey: 'kind', isShow: false, isedit: false, dwidth: 57, width: 30 },
    { key: 'Exhibit', dbkey: 'cExhibitno', isShow: true, isedit: false, dwidth: 90, width: 75 },
    { key: 'Author', dbkey: 'cAuthor', isShow: false, isedit: false, dwidth: 90, width: 75 }
  ];
  tablecols: any = [
    { id: 2, 'name': 'Tab', 'key': 'tab', 'isshow': true, },
    { id: 3, 'name': 'Exhibit No.', 'key': 'exhibit', 'isshow': true, },
    { id: 4, 'name': 'Name', 'key': 'name', 'isshow': true, },
    { id: 5, 'name': 'Pagination', 'key': 'page', 'isshow': true, },
    { id: 6, 'name': 'Kind', 'key': 'Kind', 'isshow': true, },
    { id: 7, 'name': 'Date', 'key': 'date', 'isshow': true, },
    { id: 8, 'name': 'Description', 'key': 'desc', 'isshow': true, },
    { id: 9, 'name': 'Author', 'key': 'desc', 'isshow': false }
  ];

  process: boolean = false;
  socketSubscription: Subscription;
  responceMsg: string = 'Batch file download in progress. Please wait...';
  isFailed: boolean = false;
  isGeneration: boolean = false;
  constructor(private MatDialogRef: MatDialogRef<DownloadbatchComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any, private bfService: BatchfileService, private ss: SocketService,
    private hs: HeaderService, private cdr: ChangeDetectorRef) {
    this.nCaseid = data['nCaseid'];
    this.activeSection = data['activeSection'];
    this.cFilename = this.hs.Casedetail.cCasename.replaceAll(' ', '_') + '_' + 'Batch_name'

    this.socketSubscription = this.ss.getBatchfile().subscribe((res: any) => {
      if (res.data.type != 'F' || res.data.type != 'C') {
        this.responceMsg = res.data.message;
      } if (res.data.type == 'F') {
        this.isFailed = true;
        this.process = false;
        this.responceMsg = res.data.message;
      }
      if (res.data.type == 'C') {
        this.downloadURI(res.data.data.path, res.data.data.name);
        this.process = false;
        this.MatDialogRef.close();
      }
    })

  }

  ngOnDestroy(): void {
    this.socketSubscription.unsubscribe();
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
  }

  ngOnInit(): void {
  }

  downloadBfile() {
    if (this.process) { return }
    let mdl: BatchDownloadReq = {} as BatchDownloadReq;
    mdl.cFilename = this.cFilename + '.xlsx';
    mdl.column = this.timePeriods.filter(e => e.isShow).map(x => JSON.stringify([x.key, x.dbkey])).join(',');
    mdl.nSectionid = this.activeSection.nSectionid;
    mdl.nCaseid = this.nCaseid;
    mdl.cBundleids = `{${this.selectedbatchfolder.map(e => e.nBundleid).join(',')}}`; //this.selectedbatchfolder.filter(e => e.nBundleid).length ? this.selectedbatchfolder.filter(e => e.nBundleid).map(e => e.nBundleid) : []
    this.process = true;
    this.isFailed = false;
    this.responceMsg = 'Batch file download in progress. Please wait...';
    this.bfService.downloadBatchfile(mdl).then(res => {
      if (!res) {
        this.process = false;
        this.isFailed = true;
        this.process = false;
        this.responceMsg = 'Batch file download failed. Please try again.';
      }
    })
  }



  changeFolder(event) {
    if (event == 'SUBMIT') {
      this.selectedbatchfolder = this.getSelectedFolder().map(({ nBundleid }) => ({ nBundleid }));
      this.selectedbatchfolder.forEach(element => {
        var node = this.folderCom.getBundleNode(element.nBundleid);
        element.bundle = this.folderCom.getNodePath(node).map(e => e.cBundlename)
      });

      this.selectedIDs = this.selectedbatchfolder.map(e => e.nBundleid);
    }
  }


  onMenuClosed() {
    // this.selectedbatchfolder = this.getSelectedFolder().map(({ nBundleid }) => ({ nBundleid }));
    // this.selectedbatchfolder.forEach(element => {
    //   var node = this.folderCom.getBundleNode(element.nBundleid);
    //   element.bundle = this.folderCom.getNodePath(node).map(e => e.cBundlename)
    // });
    this.isSepcomponent = false;
    this.cdr.detectChanges();
  }


  getSelectedFolder() {
    const expandedNodes: any = [];
    // Iterate through all nodes in the data source
    this.folderCom["TREE_DATA"].forEach(node => {
      // Check if the node is expanded
      if (node["cIscheck"] && !expandedNodes.find(e => e.nBundleid == node.nParentBundleid)) {
        expandedNodes.push(node);
      }
    });
    return expandedNodes;
  }

  drop(event) {
    moveItemInArray(this.timePeriods, event.previousIndex, event.currentIndex);
  }

  close() {
    this.MatDialogRef.close();
  }

  downloadURI(uri, name) {
    const fileName = uri; // The file name you want to download
    this.bfService.downloadFile(fileName).subscribe(
      (blob) => {
        const a = document.createElement('a');
        const objectUrl = URL.createObjectURL(blob);
        a.href = objectUrl;
        a.download = name;
        a.click();
        URL.revokeObjectURL(objectUrl);
      },
      (error) => {
        console.error('Download error:', error);
      }
    );
  }

  removeFolder(bundle, ind) {
    bundle.splice(ind, 1)
    this.selectedIDs = this.selectedbatchfolder.map(e => e.nBundleid);
    this.cdr.detectChanges();
  }

}
